-- setup.sql: everything the Streams accounts need in Supabase, in one file. Generated by build_setup.py, do not edit by hand.
-- Run it in the SQL editor (Run, once). Running it again is safe: it only adds what is missing and replaces functions.

create table if not exists public.schema_versions (
  name       text primary key,
  applied_at timestamptz not null default now()
);
alter table public.schema_versions enable row level security;
revoke all on public.schema_versions from anon, authenticated;

-- 1. accounts core: tables, row level security, PIN and sync functions. Skipped when public.profiles already exists. ----------
do $core$
begin
  if to_regclass('public.profiles') is null then
-- streams accounts, v2 (design: notes/06-accounts-audit-and-design.md, review notes in notes/23-accounts-architecture.md)
-- Account = Supabase auth user. Up to 5 profiles per account. Everything per profile hangs off profiles.id.
--
-- Properties this migration guarantees:
--  * Security: row level security on every table; anonymous users have no privileges; no client callable function can
--    read or change another user's data; PINs are hashed in a table no client can read; trigger functions are not callable.
--  * Multi device sync: every synced row carries the client's own timestamp; an older write never overwrites a newer
--    one (last write wins, decided in the database, so retries and out of order outboxes are safe); a batch push and an
--    incremental pull each take one round trip; server time cursors never go backwards.
--  * Audit: security relevant account events are logged and readable by the owner.
--  * PIN: one attempt counter and one lock shared by verify, set and clear (guessing through set or clear is not possible).
--  * Hygiene: retention job for event tables, everything rebuilds from this file.

create extension if not exists pgcrypto with schema extensions;

-- profiles ----------------------------------------------------------------------------------------------------------
create table public.profiles (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references auth.users (id) on delete cascade,
  name        text not null check (char_length(btrim(name)) between 1 and 30),
  avatar      text not null default 'default' check (char_length(avatar) <= 64),
  kind        text not null default 'adult' check (kind in ('adult', 'kids')),
  maturity    text not null default 'adult' check (maturity in ('little_kids', 'older_kids', 'teens', 'adult')),
  has_pin     boolean not null default false,
  sort_order  smallint not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint profiles_kids_maturity check (kind <> 'kids' or maturity in ('little_kids', 'older_kids'))
);
create unique index profiles_user_name_key on public.profiles (user_id, lower(btrim(name)));
comment on table public.profiles is 'Netflix style profiles: up to 5 per account, optional kids maturity, optional hashed PIN (profile_pins).';

create or replace function public.touch_updated_at()
returns trigger language plpgsql set search_path = '' as $$
begin
  new.updated_at := clock_timestamp();
  return new;
end $$;
create trigger profiles_touch before update on public.profiles
  for each row execute function public.touch_updated_at();

create or replace function public.enforce_profile_limit()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  -- two parallel inserts for one account must not both pass the count
  perform pg_advisory_xact_lock(hashtextextended(new.user_id::text, 0));
  if (select count(*) from public.profiles where user_id = new.user_id) >= 5 then
    raise exception 'profile limit reached' using errcode = 'P0001';
  end if;
  return new;
end $$;
create trigger profiles_limit before insert on public.profiles
  for each row execute function public.enforce_profile_limit();

-- the last profile of a live account cannot be deleted (deleting the account itself still cascades)
create or replace function public.keep_last_profile()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if exists (select 1 from auth.users u where u.id = old.user_id)
     and (select count(*) from public.profiles where user_id = old.user_id) <= 1 then
    raise exception 'an account needs at least one profile' using errcode = 'P0001';
  end if;
  return old;
end $$;
create trigger profiles_keep_last before delete on public.profiles
  for each row execute function public.keep_last_profile();

-- PIN hashes live apart from profiles; RLS is on and no policy exists, so only the functions below can touch them
create table public.profile_pins (
  profile_id       uuid primary key references public.profiles (id) on delete cascade,
  pin_hash         text not null,
  failed_attempts  smallint not null default 0,
  locked_until     timestamptz,
  updated_at       timestamptz not null default now()
);

-- audit log ---------------------------------------------------------------------------------------------------------
create table public.account_events (
  id       bigint generated always as identity primary key,
  user_id  uuid not null references auth.users (id) on delete cascade,
  ts       timestamptz not null default now(),
  event    text not null,
  meta     jsonb not null default '{}'::jsonb
);
create index account_events_user_ts_idx on public.account_events (user_id, ts desc);
comment on table public.account_events is 'Security relevant events (profile created or deleted, PIN set, cleared or locked). Written by functions only.';

create or replace function public.log_account_event(p_user uuid, p_event text, p_meta jsonb default '{}'::jsonb)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if exists (select 1 from auth.users u where u.id = p_user) then
    insert into public.account_events (user_id, event, meta) values (p_user, p_event, coalesce(p_meta, '{}'::jsonb));
  end if;
end $$;

create or replace function public.audit_profiles()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    perform public.log_account_event(new.user_id, 'profile_created', jsonb_build_object('profile_id', new.id, 'kind', new.kind));
    return new;
  end if;
  perform public.log_account_event(old.user_id, 'profile_deleted', jsonb_build_object('profile_id', old.id));
  return old;
end $$;
create trigger profiles_audit after insert or delete on public.profiles
  for each row execute function public.audit_profiles();

-- per profile data (multi device sync) ------------------------------------------------------------------------------
-- client_updated_at is the device's own clock (clamped to 5 minutes ahead of the server); updated_at is the server's
-- clock and is the pull cursor. A write with an older client_updated_at than the stored row is ignored.
create or replace function public.sync_row_guard()
returns trigger language plpgsql set search_path = '' as $$
begin
  new.client_updated_at := least(new.client_updated_at, now() + interval '5 minutes');
  if tg_op = 'UPDATE' and new.client_updated_at < old.client_updated_at then
    return null;
  end if;
  new.updated_at := clock_timestamp();
  return new;
end $$;

create table public.profile_titles (
  profile_id         uuid not null references public.profiles (id) on delete cascade,
  media_type         text not null check (media_type in ('movie', 'tv')),
  tmdb_id            integer not null check (tmdb_id > 0),
  in_list            boolean not null default false,
  rating             text check (rating in ('down', 'up', 'love')),
  added_at           timestamptz,
  client_updated_at  timestamptz not null default now(),
  updated_at         timestamptz not null default clock_timestamp(),
  primary key (profile_id, media_type, tmdb_id)
);
create index profile_titles_list_idx on public.profile_titles (profile_id, added_at desc) where in_list;
create index profile_titles_pull_idx on public.profile_titles (profile_id, updated_at);
create trigger profile_titles_guard before insert or update on public.profile_titles
  for each row execute function public.sync_row_guard();
comment on table public.profile_titles is 'My List and ratings, one row per profile and title. Removal is in_list = false so other devices learn about it.';

create table public.watch_progress (
  profile_id         uuid not null references public.profiles (id) on delete cascade,
  media_type         text not null check (media_type in ('movie', 'tv')),
  tmdb_id            integer not null check (tmdb_id > 0),
  season             smallint not null default 0 check (season >= 0),
  episode            smallint not null default 0 check (episode >= 0),
  position_seconds   integer not null default 0 check (position_seconds >= 0),
  duration_seconds   integer not null default 0 check (duration_seconds >= 0),
  completed          boolean not null default false,
  hidden             boolean not null default false,
  client_updated_at  timestamptz not null default now(),
  updated_at         timestamptz not null default clock_timestamp(),
  primary key (profile_id, media_type, tmdb_id, season, episode)
);
create index watch_progress_recent_idx on public.watch_progress (profile_id, client_updated_at desc);
create index watch_progress_pull_idx on public.watch_progress (profile_id, updated_at);
create trigger watch_progress_guard before insert or update on public.watch_progress
  for each row execute function public.sync_row_guard();
comment on table public.watch_progress is 'Continue Watching and viewing activity. hidden = removed from the viewing activity list.';

create table public.profile_settings (
  profile_id         uuid primary key references public.profiles (id) on delete cascade,
  autoplay_next      boolean not null default true,
  autoplay_previews  boolean not null default true,
  audio_language     text,
  subtitle_language  text,
  subtitle_style     jsonb not null default '{}'::jsonb,
  ui_language        text,
  client_updated_at  timestamptz not null default now(),
  updated_at         timestamptz not null default clock_timestamp()
);
create trigger profile_settings_guard before insert or update on public.profile_settings
  for each row execute function public.sync_row_guard();

create table public.profile_taste (
  profile_id     uuid primary key references public.profiles (id) on delete cascade,
  genre_weights  jsonb not null default '{}'::jsonb,
  taste_version  integer not null default 0,
  updated_at     timestamptz not null default clock_timestamp()
);
create trigger profile_taste_touch before update on public.profile_taste
  for each row execute function public.touch_updated_at();

create table public.feed_events (
  id          bigint generated always as identity primary key,
  profile_id  uuid not null references public.profiles (id) on delete cascade,
  ts          timestamptz not null default now(),
  event       text not null check (event in ('impression', 'click', 'start', 'complete', 'like', 'skip', 'add_list', 'remove_list')),
  media_type  text check (media_type in ('movie', 'tv')),
  tmdb_id     integer,
  row_title   text,
  position    smallint
);
create index feed_events_profile_ts_idx on public.feed_events (profile_id, ts desc);

create or replace function public.create_profile_defaults()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  insert into public.profile_settings (profile_id) values (new.id) on conflict do nothing;
  return new;
end $$;
create trigger profiles_defaults after insert on public.profiles
  for each row execute function public.create_profile_defaults();

create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  insert into public.profiles (user_id, name)
  values (
    new.id,
    left(coalesce(nullif(btrim(new.raw_user_meta_data ->> 'full_name'), ''),
                  nullif(split_part(coalesce(new.email, ''), '@', 1), ''), 'Me'), 30)
  );
  return new;
end $$;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- sync API: one round trip each way; both run with the caller's rights, so row level security decides what is visible ---
create or replace function public.sync_push(p_profile uuid, p_titles jsonb default '[]'::jsonb, p_progress jsonb default '[]'::jsonb)
returns jsonb language plpgsql security invoker set search_path = '' as $$
declare
  n_titles   integer := 0;
  n_progress integer := 0;
begin
  if jsonb_array_length(p_titles) > 500 or jsonb_array_length(p_progress) > 500 then
    raise exception 'batch too large' using errcode = '54000';
  end if;

  insert into public.profile_titles (profile_id, media_type, tmdb_id, in_list, rating, added_at, client_updated_at)
  select p_profile, r.media_type, r.tmdb_id, coalesce(r.in_list, false), r.rating, r.added_at, coalesce(r.client_updated_at, now())
  from jsonb_to_recordset(p_titles) as r(media_type text, tmdb_id integer, in_list boolean, rating text, added_at timestamptz, client_updated_at timestamptz)
  on conflict (profile_id, media_type, tmdb_id) do update
    set in_list = excluded.in_list, rating = excluded.rating, added_at = excluded.added_at,
        client_updated_at = excluded.client_updated_at;
  get diagnostics n_titles = row_count;

  insert into public.watch_progress (profile_id, media_type, tmdb_id, season, episode, position_seconds, duration_seconds, completed, hidden, client_updated_at)
  select p_profile, r.media_type, r.tmdb_id, coalesce(r.season, 0), coalesce(r.episode, 0), coalesce(r.position_seconds, 0),
         coalesce(r.duration_seconds, 0), coalesce(r.completed, false), coalesce(r.hidden, false), coalesce(r.client_updated_at, now())
  from jsonb_to_recordset(p_progress) as r(media_type text, tmdb_id integer, season smallint, episode smallint, position_seconds integer,
                                           duration_seconds integer, completed boolean, hidden boolean, client_updated_at timestamptz)
  on conflict (profile_id, media_type, tmdb_id, season, episode) do update
    set position_seconds = excluded.position_seconds, duration_seconds = excluded.duration_seconds,
        completed = excluded.completed, hidden = excluded.hidden, client_updated_at = excluded.client_updated_at;
  get diagnostics n_progress = row_count;

  return jsonb_build_object('titles', n_titles, 'progress', n_progress, 'server_time', clock_timestamp());
end $$;

-- changes since a cursor (use the returned cursor next time); has_more means pull again
create or replace function public.sync_pull(p_profile uuid, p_since timestamptz default 'epoch')
returns jsonb language plpgsql stable security invoker set search_path = '' as $$
declare
  v_titles    jsonb;
  v_progress  jsonb;
  v_settings  jsonb;
  -- the cursor trails the clock by 5 seconds: a row written by a slower, still open transaction gets an older updated_at
  -- than rows already pulled, and would be skipped forever otherwise. Repeats are harmless, clients merge by client_updated_at.
  v_cursor    timestamptz := clock_timestamp() - interval '5 seconds';
  v_t_n       integer;
  v_p_n       integer;
  v_t_max     timestamptz;
  v_p_max     timestamptz;
  v_limit     constant integer := 2000;
begin
  select coalesce(jsonb_agg(to_jsonb(t) - 'profile_id' order by t.updated_at), '[]'::jsonb), count(*), max(t.updated_at)
    into v_titles, v_t_n, v_t_max
    from (select * from public.profile_titles where profile_id = p_profile and updated_at > p_since order by updated_at limit v_limit) t;
  select coalesce(jsonb_agg(to_jsonb(w) - 'profile_id' order by w.updated_at), '[]'::jsonb), count(*), max(w.updated_at)
    into v_progress, v_p_n, v_p_max
    from (select * from public.watch_progress where profile_id = p_profile and updated_at > p_since order by updated_at limit v_limit) w;
  select to_jsonb(s) - 'profile_id' into v_settings
    from public.profile_settings s where s.profile_id = p_profile and s.updated_at > p_since;
  if v_t_n >= v_limit then v_cursor := least(v_cursor, v_t_max); end if;
  if v_p_n >= v_limit then v_cursor := least(v_cursor, v_p_max); end if;
  v_cursor := greatest(v_cursor, p_since);
  return jsonb_build_object('cursor', v_cursor, 'has_more', (v_t_n >= v_limit or v_p_n >= v_limit),
                            'titles', v_titles, 'progress', v_progress, 'settings', v_settings);
end $$;

-- PIN functions (the only way to read or write a PIN) -------------------------------------------------------------------
-- Every comparison of a PIN goes through pin_attempt, so verifying, changing and clearing share one attempt counter and one
-- lock (5 wrong tries lock the profile for 15 minutes). Without that, set or clear could be used to guess the PIN.
-- The row is locked while counting, so parallel guesses cannot all read the same counter. A wrong PIN returns false instead
-- of raising, because an exception would roll back the counter update.
create or replace function public.pin_attempt(p_profile uuid, p_pin text)
returns boolean language plpgsql security definer set search_path = '' as $$
declare
  v_owner  uuid;
  v_row    public.profile_pins%rowtype;
  v_failed smallint;
begin
  select user_id into v_owner from public.profiles where id = p_profile;
  if v_owner is null or v_owner is distinct from (select auth.uid()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into v_row from public.profile_pins where profile_id = p_profile for update;
  if not found then
    return true;
  end if;
  if v_row.locked_until is not null and v_row.locked_until > now() then
    raise exception 'too many attempts, try again later' using errcode = '55000';
  end if;
  if p_pin is not null and extensions.crypt(p_pin, v_row.pin_hash) = v_row.pin_hash then
    update public.profile_pins set failed_attempts = 0, locked_until = null where profile_id = p_profile;
    return true;
  end if;
  v_failed := v_row.failed_attempts + 1;
  if v_failed >= 5 then
    update public.profile_pins set failed_attempts = 0, locked_until = now() + interval '15 minutes' where profile_id = p_profile;
    perform public.log_account_event(v_owner, 'pin_locked', jsonb_build_object('profile_id', p_profile));
  else
    update public.profile_pins set failed_attempts = v_failed where profile_id = p_profile;
  end if;
  return false;
end $$;

-- true when the PIN matches or none is set
create or replace function public.verify_profile_pin(p_profile uuid, p_pin text)
returns boolean language sql security definer set search_path = '' as $$
  select public.pin_attempt(p_profile, p_pin);
$$;

-- true when the PIN was set; false when the current PIN was wrong (counted); raises when the current PIN is missing or the profile is locked
create or replace function public.set_profile_pin(p_profile uuid, p_pin text, p_current text default null)
returns boolean language plpgsql security definer set search_path = '' as $$
declare
  v_owner uuid;
  v_has   boolean;
begin
  select user_id into v_owner from public.profiles where id = p_profile;
  if v_owner is null or v_owner is distinct from (select auth.uid()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_pin !~ '^[0-9]{4}$' then
    raise exception 'the PIN is 4 digits' using errcode = '22023';
  end if;
  select exists (select 1 from public.profile_pins where profile_id = p_profile) into v_has;
  if v_has then
    if p_current is null then
      raise exception 'the current PIN is required' using errcode = '28000';
    end if;
    if not public.pin_attempt(p_profile, p_current) then
      return false;
    end if;
  end if;
  insert into public.profile_pins (profile_id, pin_hash)
  values (p_profile, extensions.crypt(p_pin, extensions.gen_salt('bf', 10)))
  on conflict (profile_id) do update
    set pin_hash = excluded.pin_hash, failed_attempts = 0, locked_until = null, updated_at = now();
  update public.profiles set has_pin = true where id = p_profile;
  perform public.log_account_event(v_owner, 'pin_set', jsonb_build_object('profile_id', p_profile));
  return true;
end $$;

-- true when cleared (or none was set); false when the current PIN was wrong (counted)
create or replace function public.clear_profile_pin(p_profile uuid, p_current text)
returns boolean language plpgsql security definer set search_path = '' as $$
declare
  v_owner uuid;
  v_has   boolean;
begin
  select user_id into v_owner from public.profiles where id = p_profile;
  if v_owner is null or v_owner is distinct from (select auth.uid()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select exists (select 1 from public.profile_pins where profile_id = p_profile) into v_has;
  if not v_has then
    return true;
  end if;
  if p_current is null then
    raise exception 'the current PIN is required' using errcode = '28000';
  end if;
  if not public.pin_attempt(p_profile, p_current) then
    return false;
  end if;
  delete from public.profile_pins where profile_id = p_profile;
  update public.profiles set has_pin = false where id = p_profile;
  perform public.log_account_event(v_owner, 'pin_cleared', jsonb_build_object('profile_id', p_profile));
  return true;
end $$;

create or replace function public.delete_my_account()
returns void language plpgsql security definer set search_path = '' as $$
begin
  if (select auth.uid()) is null then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  delete from auth.users where id = (select auth.uid());
end $$;

-- row level security ------------------------------------------------------------------------------------------------------
alter table public.profiles         enable row level security;
alter table public.profile_pins     enable row level security;
alter table public.account_events   enable row level security;
alter table public.profile_titles   enable row level security;
alter table public.watch_progress   enable row level security;
alter table public.profile_settings enable row level security;
alter table public.profile_taste    enable row level security;
alter table public.feed_events      enable row level security;

create policy profiles_owner on public.profiles for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy account_events_owner on public.account_events for select to authenticated
  using (user_id = (select auth.uid()));

create policy owner_all on public.profile_titles for all to authenticated
  using (exists (select 1 from public.profiles p where p.id = profile_titles.profile_id and p.user_id = (select auth.uid())))
  with check (exists (select 1 from public.profiles p where p.id = profile_titles.profile_id and p.user_id = (select auth.uid())));
create policy owner_all on public.watch_progress for all to authenticated
  using (exists (select 1 from public.profiles p where p.id = watch_progress.profile_id and p.user_id = (select auth.uid())))
  with check (exists (select 1 from public.profiles p where p.id = watch_progress.profile_id and p.user_id = (select auth.uid())));
create policy owner_all on public.profile_settings for all to authenticated
  using (exists (select 1 from public.profiles p where p.id = profile_settings.profile_id and p.user_id = (select auth.uid())))
  with check (exists (select 1 from public.profiles p where p.id = profile_settings.profile_id and p.user_id = (select auth.uid())));
create policy owner_all on public.profile_taste for all to authenticated
  using (exists (select 1 from public.profiles p where p.id = profile_taste.profile_id and p.user_id = (select auth.uid())))
  with check (exists (select 1 from public.profiles p where p.id = profile_taste.profile_id and p.user_id = (select auth.uid())));
create policy owner_select on public.feed_events for select to authenticated
  using (exists (select 1 from public.profiles p where p.id = feed_events.profile_id and p.user_id = (select auth.uid())));
create policy owner_insert on public.feed_events for insert to authenticated
  with check (exists (select 1 from public.profiles p where p.id = feed_events.profile_id and p.user_id = (select auth.uid())));

-- privileges ----------------------------------------------------------------------------------------------------------------
revoke all on public.profiles, public.profile_pins, public.account_events, public.profile_titles, public.watch_progress,
              public.profile_settings, public.profile_taste, public.feed_events from anon, authenticated;
grant select, delete on public.profiles to authenticated;
grant insert (user_id, name, avatar, kind, maturity, sort_order) on public.profiles to authenticated;
grant update (name, avatar, kind, maturity, sort_order) on public.profiles to authenticated;
grant select on public.account_events to authenticated;
grant select, insert, update, delete on public.profile_titles, public.watch_progress,
                                        public.profile_settings, public.profile_taste to authenticated;
grant select, insert on public.feed_events to authenticated;

revoke all on function public.touch_updated_at(), public.sync_row_guard(), public.enforce_profile_limit(), public.keep_last_profile(),
                       public.log_account_event(uuid, text, jsonb), public.audit_profiles(), public.create_profile_defaults(),
                       public.handle_new_user(), public.pin_attempt(uuid, text) from public, anon, authenticated;
revoke all on function public.sync_push(uuid, jsonb, jsonb), public.sync_pull(uuid, timestamptz),
                       public.set_profile_pin(uuid, text, text), public.clear_profile_pin(uuid, text),
                       public.verify_profile_pin(uuid, text), public.delete_my_account() from public, anon;
grant execute on function public.sync_push(uuid, jsonb, jsonb), public.sync_pull(uuid, timestamptz),
                          public.set_profile_pin(uuid, text, text), public.clear_profile_pin(uuid, text),
                          public.verify_profile_pin(uuid, text), public.delete_my_account() to authenticated;

alter default privileges in schema public revoke all on tables from anon;
alter default privileges in schema public revoke all on functions from anon;


  end if;
end $core$;
insert into public.schema_versions (name) values ('accounts_core') on conflict do nothing;

-- realtime and retention (each block catches its own errors, so they can be repeated)
-- realtime for live multi device updates (rows still pass row level security) and retention of event tables --------------------
do $$
begin
  alter publication supabase_realtime add table public.profile_titles, public.watch_progress, public.profile_settings;
exception when others then
  raise notice 'realtime publication not updated: %', sqlerrm;
end $$;

do $$
begin
  create extension if not exists pg_cron;
  perform cron.schedule('prune-feed-events', '17 3 * * *', $job$delete from public.feed_events where ts < now() - interval '180 days'$job$);
  perform cron.schedule('prune-account-events', '23 3 * * *', $job$delete from public.account_events where ts < now() - interval '365 days'$job$);
exception when others then
  raise notice 'retention jobs not scheduled: %', sqlerrm;
end $$;


-- 2. main profile, Kids profile, account details, recent sign in checks, data export --------------------------------------------
-- Accounts, second step (owner decisions of 2026-10-11).
--   * The account asks for a first and a last name at signup. The main profile is named after the first name.
--   * Every account gets a Kids profile with the striped icon. It can be deleted and does not count toward the limit of five.
--   * The main profile can be moved to another profile after the person proves who they are again.
--   * Actions that a child on a signed in parent session must not be able to do (moving the main profile, changing a profile to
--     Kids or adult, resetting a PIN, deleting the account) need a password entry in the last five minutes.
-- Everything here can be run again: columns, tables and indexes are created only when missing, functions are replaced, and the
-- backfill touches only accounts that still need it.

alter table public.profiles add column if not exists is_main boolean not null default false;
alter table public.profiles add column if not exists auto_kids boolean not null default false;
create unique index if not exists profiles_one_main on public.profiles (user_id) where is_main;
create unique index if not exists profiles_one_auto_kids on public.profiles (user_id) where auto_kids;

-- Name of the person behind the account (shown on the Account page; the main profile starts from the first name) ----------------
create table if not exists public.account_details (
  user_id    uuid primary key references auth.users (id) on delete cascade,
  first_name text not null default '' check (char_length(first_name) <= 60),
  last_name  text not null default '' check (char_length(last_name) <= 60),
  updated_at timestamptz not null default now()
);
comment on table public.account_details is 'First and last name given at signup. Changed only through update_account_names.';
alter table public.account_details enable row level security;
drop policy if exists account_details_owner_select on public.account_details;
create policy account_details_owner_select on public.account_details for select to authenticated
  using (user_id = (select auth.uid()));
revoke all on public.account_details from anon, authenticated;
grant select on public.account_details to authenticated;

-- Proof of a recent sign in -------------------------------------------------------------------------------------------------
-- The time the password (or a one time code, link or provider) was last used is in the token's authentication methods (amr). A
-- token refresh keeps that time, so a stolen refresh token cannot pass for a fresh sign in the way the token's own issue time
-- could. The app asks for the password again, which creates a new sign in, before it calls one of the functions below.
create or replace function public.require_recent_sign_in(p_seconds integer default 300) returns void
language plpgsql stable set search_path = public as $$
declare
  v_last bigint;
begin
  select max((e ->> 'timestamp')::bigint) into v_last
    from jsonb_array_elements(coalesce(auth.jwt() -> 'amr', '[]'::jsonb)) e
   where e ->> 'method' in ('password', 'otp', 'magiclink', 'oauth');
  if v_last is null or extract(epoch from now())::bigint - v_last > p_seconds then
    raise exception 'recent sign in required' using errcode = '28000';
  end if;
end $$;

-- The two flags, the Kids rules and the sensitive changes ----------------------------------------------------------------------
-- Columns is_main and auto_kids are not granted to clients at all; this trigger is a second lock, and it adds the rule that
-- changing a profile between Kids and adult, or its maturity, needs a recent sign in.
create or replace function public.profile_flags_guard() returns trigger
language plpgsql set search_path = public as $$
begin
  if new.is_main and new.kind = 'kids' then
    raise exception 'a Kids profile cannot be the main profile' using errcode = '22023';
  end if;
  if coalesce(current_setting('streams.flags', true), '') = 'on' then
    return new;
  end if;
  if tg_op = 'INSERT' and (new.is_main or new.auto_kids) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if tg_op = 'UPDATE' then
    if new.is_main is distinct from old.is_main or new.auto_kids is distinct from old.auto_kids then
      raise exception 'not allowed' using errcode = '42501';
    end if;
    if new.kind is distinct from old.kind or new.maturity is distinct from old.maturity then
      perform public.require_recent_sign_in();
    end if;
  end if;
  return new;
end $$;

drop trigger if exists profiles_flags_guard on public.profiles;
create trigger profiles_flags_guard before insert or update on public.profiles
  for each row execute function public.profile_flags_guard();

-- Five profiles per account. The automatic Kids profile is not counted.
create or replace function public.enforce_profile_limit() returns trigger
language plpgsql set search_path = public as $$
begin
  if new.auto_kids then
    return new;
  end if;
  -- two parallel inserts for one account must not both pass the count
  perform pg_advisory_xact_lock(hashtextextended(new.user_id::text, 0));
  if (select count(*) from public.profiles where user_id = new.user_id and not auto_kids) >= 5 then
    raise exception 'profile limit reached' using errcode = 'P0001';
  end if;
  return new;
end $$;

-- A new account gets its details, its main profile (named after the first name) and the Kids profile.
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public, auth as $$
declare
  v_first text := left(coalesce(nullif(btrim(new.raw_user_meta_data ->> 'first_name'), ''), ''), 60);
  v_last  text := left(coalesce(nullif(btrim(new.raw_user_meta_data ->> 'last_name'), ''), ''), 60);
  v_name  text;
begin
  perform set_config('streams.flags', 'on', true);
  insert into public.account_details (user_id, first_name, last_name) values (new.id, v_first, v_last)
    on conflict (user_id) do nothing;
  v_name := left(
    coalesce(
      nullif(v_first, ''),
      nullif(btrim(new.raw_user_meta_data ->> 'full_name'), ''),
      nullif(split_part(coalesce(new.email, ''), '@', 1), ''),
      'Me'),
    30);
  if lower(btrim(v_name)) = 'kids' then
    v_name := 'Me';
  end if;
  insert into public.profiles (user_id, name, is_main, sort_order) values (new.id, v_name, true, 0);
  insert into public.profiles (user_id, name, avatar, kind, maturity, auto_kids, sort_order)
  values (new.id, 'Kids', 'kids', 'kids', 'older_kids', true, 1);
  perform set_config('streams.flags', 'off', true);
  return new;
end $$;

-- The last profile stays, and so does the main one until another profile has taken its place.
create or replace function public.keep_last_profile() returns trigger
-- security definer: it reads auth.users, which the signed in role may not read (deleting a profile from the app would fail otherwise)
language plpgsql security definer set search_path = public, auth as $$
begin
  if exists (select 1 from auth.users u where u.id = old.user_id) then
    if (select count(*) from public.profiles where user_id = old.user_id) <= 1 then
      raise exception 'an account needs at least one profile' using errcode = 'P0001';
    end if;
    if old.is_main then
      raise exception 'make another profile the main one before deleting this one' using errcode = 'P0001';
    end if;
  end if;
  return old;
end $$;

-- Functions the app calls ------------------------------------------------------------------------------------------------------
create or replace function public.set_main_profile(p_profile uuid) returns void
language plpgsql security definer set search_path = public, auth as $$
declare
  v_owner uuid;
  v_kind  text;
begin
  select user_id, kind into v_owner, v_kind from public.profiles where id = p_profile;
  if v_owner is null or v_owner is distinct from (select auth.uid()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if v_kind = 'kids' then
    raise exception 'a Kids profile cannot be the main profile' using errcode = '22023';
  end if;
  perform public.require_recent_sign_in();
  perform set_config('streams.flags', 'on', true);
  update public.profiles set is_main = false where user_id = v_owner and is_main and id <> p_profile;
  update public.profiles set is_main = true where id = p_profile;
  perform set_config('streams.flags', 'off', true);
  perform public.log_account_event(v_owner, 'main_profile_changed', jsonb_build_object('profile_id', p_profile));
end $$;

-- Forgot the PIN: after entering the account password again, the PIN of one of your profiles is removed and a new one can be set.
create or replace function public.reset_profile_pin(p_profile uuid) returns void
language plpgsql security definer set search_path = public, auth as $$
declare
  v_owner uuid;
begin
  select user_id into v_owner from public.profiles where id = p_profile;
  if v_owner is null or v_owner is distinct from (select auth.uid()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform public.require_recent_sign_in();
  delete from public.profile_pins where profile_id = p_profile;
  perform set_config('streams.flags', 'on', true);
  update public.profiles set has_pin = false where id = p_profile;
  perform set_config('streams.flags', 'off', true);
  perform public.log_account_event(v_owner, 'pin_reset', jsonb_build_object('profile_id', p_profile));
end $$;

-- Change the first or last name. The main profile follows when it still carries the old first name.
create or replace function public.update_account_names(p_first text, p_last text) returns void
language plpgsql security definer set search_path = public, auth as $$
declare
  v_user uuid := (select auth.uid());
  v_old  text;
  v_first text := left(btrim(coalesce(p_first, '')), 60);
  v_last  text := left(btrim(coalesce(p_last, '')), 60);
begin
  if v_user is null then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if v_first = '' or v_last = '' then
    raise exception 'first and last name are required' using errcode = '22023';
  end if;
  select first_name into v_old from public.account_details where user_id = v_user;
  insert into public.account_details (user_id, first_name, last_name) values (v_user, v_first, v_last)
    on conflict (user_id) do update set first_name = excluded.first_name, last_name = excluded.last_name, updated_at = now();
  update auth.users
     set raw_user_meta_data = coalesce(raw_user_meta_data, '{}'::jsonb)
         || jsonb_build_object('first_name', v_first, 'last_name', v_last, 'full_name', btrim(v_first || ' ' || v_last))
   where id = v_user;
  update public.profiles set name = left(v_first, 30)
   where user_id = v_user and is_main and lower(btrim(name)) = lower(btrim(coalesce(v_old, '')))
     and not exists (select 1 from public.profiles o where o.user_id = v_user and not o.is_main and lower(btrim(o.name)) = lower(btrim(left(v_first, 30))));
end $$;

-- Delete the account, only right after the password has been entered again.
create or replace function public.delete_my_account() returns void
language plpgsql security definer set search_path = '' as $$
begin
  if (select auth.uid()) is null then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform public.require_recent_sign_in();
  delete from auth.users where id = (select auth.uid());
end $$;

-- Everything held about the signed in person, for the right of access in the Privacy Policy. Row level security applies, so it
-- can only ever return their own rows. PIN hashes are not included.
create or replace function public.export_my_data() returns jsonb
language sql stable security invoker set search_path = public as $$
  select jsonb_build_object(
    'exported_at', now(),
    'account', (select to_jsonb(a) - 'user_id' from public.account_details a limit 1),
    'profiles', (select coalesce(jsonb_agg(to_jsonb(p) - 'user_id' order by p.sort_order), '[]'::jsonb) from public.profiles p),
    'my_list_and_ratings', (select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) from public.profile_titles t),
    'watch_progress', (select coalesce(jsonb_agg(to_jsonb(w)), '[]'::jsonb) from public.watch_progress w),
    'settings', (select coalesce(jsonb_agg(to_jsonb(s)), '[]'::jsonb) from public.profile_settings s),
    'security_events', (select coalesce(jsonb_agg(to_jsonb(e) - 'user_id' order by e.ts desc), '[]'::jsonb) from public.account_events e)
  )
$$;

revoke all on function public.require_recent_sign_in(integer), public.profile_flags_guard(), public.handle_new_user(), public.keep_last_profile(), public.enforce_profile_limit() from public, anon, authenticated;
revoke all on function public.set_main_profile(uuid), public.reset_profile_pin(uuid), public.update_account_names(text, text), public.delete_my_account(), public.export_my_data() from public, anon;
grant execute on function public.set_main_profile(uuid), public.reset_profile_pin(uuid), public.update_account_names(text, text), public.delete_my_account(), public.export_my_data() to authenticated;
grant execute on function public.require_recent_sign_in(integer) to authenticated;

-- Accounts that existed before this step: details from the signup data, and the oldest adult profile becomes the main one. ------
do $$
begin
  perform set_config('streams.flags', 'on', true);
  insert into public.account_details (user_id, first_name, last_name)
  select u.id, left(coalesce(u.raw_user_meta_data ->> 'first_name', ''), 60), left(coalesce(u.raw_user_meta_data ->> 'last_name', ''), 60)
    from auth.users u
  on conflict (user_id) do nothing;
  update public.profiles p set is_main = true
   where p.id in (select distinct on (user_id) id from public.profiles where kind = 'adult' order by user_id, created_at)
     and not exists (select 1 from public.profiles m where m.user_id = p.user_id and m.is_main);
  perform set_config('streams.flags', 'off', true);
end $$;

insert into public.schema_versions (name) values ('main_profile_and_default_kids') on conflict do nothing;

-- 3. devices, per profile preferences, account switches ---------------------------------------------------------------------------
-- Devices (the account's sessions), per profile preferences and account switches. Every statement can be repeated.
-- Design: notes/32-settings-rebuild-plan-2026-10-11.md and 33-settings-gap-list-2026-10-11.md in the project notes.

-- Preferences kept per profile, next to the existing autoplay and language columns ---------------------------------------------
alter table public.profile_settings add column if not exists data_usage text not null default 'auto';
alter table public.profile_settings add column if not exists notifications jsonb not null default '{}'::jsonb;
alter table public.profile_settings add column if not exists blocked_titles jsonb not null default '[]'::jsonb;
alter table public.profile_settings add column if not exists game_handle text;
-- Highest British (BBFC) rating a profile may see. 18 means no limit. The older profiles.maturity column is kept and follows it.
alter table public.profile_settings add column if not exists age_rating text not null default '18';
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'profile_settings_data_usage_check') then
    alter table public.profile_settings add constraint profile_settings_data_usage_check check (data_usage in ('auto', 'low', 'medium', 'high'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'profile_settings_age_rating_check') then
    alter table public.profile_settings add constraint profile_settings_age_rating_check check (age_rating in ('U', 'PG', '12', '15', '18'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'profile_settings_game_handle_check') then
    alter table public.profile_settings add constraint profile_settings_game_handle_check check (game_handle is null or game_handle ~ '^[A-Za-z0-9]{3,16}$');
  end if;
  if not exists (select 1 from pg_constraint where conname = 'profile_settings_blocked_titles_check') then
    alter table public.profile_settings add constraint profile_settings_blocked_titles_check check (jsonb_typeof(blocked_titles) = 'array' and jsonb_array_length(blocked_titles) <= 200);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'profile_settings_notifications_check') then
    alter table public.profile_settings add constraint profile_settings_notifications_check check (jsonb_typeof(notifications) = 'object');
  end if;
end $$;
create unique index if not exists profile_settings_game_handle_key on public.profile_settings (lower(game_handle)) where game_handle is not null;

-- Switches of the whole account --------------------------------------------------------------------------------------------------
alter table public.account_details add column if not exists test_participation boolean not null default true;
alter table public.account_details add column if not exists profile_transfer boolean not null default true;

create or replace function public.set_account_switch(p_name text, p_value boolean) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_user uuid := (select auth.uid());
begin
  if v_user is null then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_name not in ('test_participation', 'profile_transfer') then
    raise exception 'unknown switch' using errcode = '22023';
  end if;
  insert into public.account_details (user_id) values (v_user) on conflict (user_id) do nothing;
  if p_name = 'test_participation' then
    update public.account_details set test_participation = p_value, updated_at = now() where user_id = v_user;
  else
    update public.account_details set profile_transfer = p_value, updated_at = now() where user_id = v_user;
  end if;
  perform public.log_account_event(v_user, 'switch_' || p_name, jsonb_build_object('value', p_value));
end $$;

-- Devices: the list of sessions (list_my_sessions) is defined in 20261012200000_device_signature.sql, with the device details.
create or replace function public.revoke_my_session(p_id uuid) returns void
language plpgsql security definer set search_path = auth, public as $$
declare
  v_user uuid := (select auth.uid());
begin
  if v_user is null then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  perform public.require_recent_sign_in();
  delete from auth.sessions where id = p_id and user_id = v_user;
  perform public.log_account_event(v_user, 'session_revoked', jsonb_build_object('session_id', p_id));
end $$;

revoke all on function public.set_account_switch(text, boolean), public.revoke_my_session(uuid) from public, anon;
grant execute on function public.set_account_switch(text, boolean), public.revoke_my_session(uuid) to authenticated;

-- the data export includes the new columns through the existing tables; nothing else to change

insert into public.schema_versions (name) values ('devices_and_profile_preferences') on conflict do nothing;

-- 4. device signature: recognise each browser by an id it keeps, never by its connection address -------------------------------------
-- Device signature: each browser that signs in is recognised by an id it keeps for itself plus what it says about itself (browser,
-- system, kind of device, language, time zone, screen size) and the country it connects from. The address of the connection is
-- never stored. Every statement can be repeated.
--
-- Rules for a VPN or travel: a device is the same device when it presents the same id, wherever it connects from. A different
-- country only adds to the countries seen for that device and writes a quiet log entry (device_new_country). Only an id that
-- has not been seen before is a new device (log entry new_device), and the app can tell the owner about it.

create table if not exists public.account_devices (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null references auth.users (id) on delete cascade,
  device_key     text not null check (char_length(device_key) between 16 and 64),
  browser        text check (char_length(browser) <= 60),
  browser_major  integer,
  os             text check (char_length(os) <= 60),
  device_type    text not null default 'other' check (device_type in ('desktop', 'mobile', 'tablet', 'tv', 'other')),
  language       text check (char_length(language) <= 20),
  timezone       text check (char_length(timezone) <= 60),
  screen         text check (char_length(screen) <= 20),
  user_agent     text check (char_length(user_agent) <= 400),
  last_country   text check (last_country ~ '^[A-Z]{2}$'),
  countries      text[] not null default '{}',
  session_id     uuid,
  first_seen     timestamptz not null default now(),
  last_seen      timestamptz not null default now(),
  unique (user_id, device_key)
);
create index if not exists account_devices_user_idx on public.account_devices (user_id, last_seen desc);
comment on table public.account_devices is 'Browsers and devices that signed in to an account. Written only by register_device; the connection address is not kept.';
alter table public.account_devices enable row level security;
drop policy if exists account_devices_owner_select on public.account_devices;
create policy account_devices_owner_select on public.account_devices for select to authenticated using (user_id = (select auth.uid()));
revoke all on public.account_devices from anon, authenticated;
grant select on public.account_devices to authenticated;

-- Called by the app after every sign in and when it starts signed in. p_info holds: browser, browser_major, os, device_type,
-- language, timezone, screen, user_agent, country (two capital letters, from the edge, may be missing).
create or replace function public.register_device(p_device_key text, p_info jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_user     uuid := (select auth.uid());
  v_session  uuid := nullif(auth.jwt() ->> 'session_id', '')::uuid;
  v_country  text := upper(nullif(left(coalesce(p_info ->> 'country', ''), 8), ''));
  v_type     text := coalesce(nullif(p_info ->> 'device_type', ''), 'other');
  v_row      public.account_devices%rowtype;
  v_new      boolean := false;
  v_new_country boolean := false;
begin
  if v_user is null then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_device_key is null or char_length(p_device_key) not between 16 and 64 then
    raise exception 'invalid device key' using errcode = '22023';
  end if;
  if v_country is not null and v_country !~ '^[A-Z]{2}$' then v_country := null; end if;
  if v_type not in ('desktop', 'mobile', 'tablet', 'tv', 'other') then v_type := 'other'; end if;

  select * into v_row from public.account_devices where user_id = v_user and device_key = p_device_key;
  if not found then
    v_new := true;
    insert into public.account_devices (user_id, device_key, browser, browser_major, os, device_type, language, timezone, screen, user_agent, last_country, countries, session_id)
    values (v_user, p_device_key, left(p_info ->> 'browser', 60), nullif(p_info ->> 'browser_major', '')::integer, left(p_info ->> 'os', 60), v_type,
            left(p_info ->> 'language', 20), left(p_info ->> 'timezone', 60), left(p_info ->> 'screen', 20), left(p_info ->> 'user_agent', 400),
            v_country, case when v_country is null then '{}'::text[] else array[v_country] end, v_session)
    returning * into v_row;
    perform public.log_account_event(v_user, 'new_device', jsonb_build_object('device', v_row.id, 'browser', v_row.browser, 'os', v_row.os, 'country', v_country));
  else
    v_new_country := v_country is not null and not (v_country = any (v_row.countries));
    update public.account_devices
       set browser = coalesce(left(p_info ->> 'browser', 60), browser), browser_major = coalesce(nullif(p_info ->> 'browser_major', '')::integer, browser_major),
           os = coalesce(left(p_info ->> 'os', 60), os), device_type = case when v_type = 'other' then device_type else v_type end,
           language = coalesce(left(p_info ->> 'language', 20), language), timezone = coalesce(left(p_info ->> 'timezone', 60), timezone),
           screen = coalesce(left(p_info ->> 'screen', 20), screen), user_agent = coalesce(left(p_info ->> 'user_agent', 400), user_agent),
           last_country = coalesce(v_country, last_country),
           countries = case when v_new_country then array_append(countries, v_country) else countries end,
           session_id = coalesce(v_session, session_id), last_seen = now()
     where id = v_row.id returning * into v_row;
    if v_new_country then
      perform public.log_account_event(v_user, 'device_new_country', jsonb_build_object('device', v_row.id, 'country', v_country));
    end if;
  end if;
  return jsonb_build_object('device_id', v_row.id, 'is_new', v_new, 'new_country', v_new_country, 'countries', v_row.countries);
end $$;

-- The device list: every session of the account with what is known about the browser that made it. A session with no device
-- row (it signed in before this existed) is still listed, with the browser text Supabase recorded.
drop function if exists public.list_my_sessions();
create or replace function public.list_my_sessions()
returns table (id uuid, created_at timestamptz, last_seen timestamptz, user_agent text, is_current boolean,
               device_id uuid, browser text, browser_major integer, os text, device_type text, language text, timezone text, screen text,
               country text, countries text[], device_first_seen timestamptz)
language sql stable security definer set search_path = auth, public as $$
  select s.id, s.created_at, coalesce(s.refreshed_at, s.updated_at, s.created_at), coalesce(d.user_agent, s.user_agent),
         s.id = nullif(auth.jwt() ->> 'session_id', '')::uuid,
         d.id, d.browser, d.browser_major, d.os, d.device_type, d.language, d.timezone, d.screen, d.last_country, d.countries, d.first_seen
    from auth.sessions s
    left join public.account_devices d on d.user_id = s.user_id and d.session_id = s.id
   where s.user_id = (select auth.uid())
   order by coalesce(s.refreshed_at, s.updated_at, s.created_at) desc nulls last
   limit 50
$$;

revoke all on function public.register_device(text, jsonb), public.list_my_sessions() from public, anon;
grant execute on function public.register_device(text, jsonb), public.list_my_sessions() to authenticated;

insert into public.schema_versions (name) values ('device_signature') on conflict do nothing;

-- 5. rating labels: british or american, by account choice or the country of the device ------------------------------------------
-- Which age rating labels a person reads: the British ones (U, PG, 12, 15, 18) or the American ones (G, PG, PG-13, R, NC-17, TV-...).
-- The account can choose ('uk' or 'us'); the default 'auto' follows the country of the device this session signed in from (the device
-- signature, see account_devices.last_country). The country to system table is data, not code: add a row to change a country.
-- Every statement can be repeated.

create table if not exists public.rating_system_by_country (
  country text primary key check (country ~ '^[A-Z]{2}$'),
  system  text not null check (system in ('uk', 'us'))
);
comment on table public.rating_system_by_country is 'Rating labels by country for accounts on auto. A country not listed gets the british labels.';
insert into public.rating_system_by_country (country, system) values
  ('US', 'us'), ('CA', 'us'), ('MX', 'us'), ('PR', 'us'), ('GU', 'us'), ('VI', 'us'), ('AS', 'us'), ('MP', 'us'),
  ('GB', 'uk'), ('IE', 'uk')
on conflict (country) do nothing;
alter table public.rating_system_by_country enable row level security;
drop policy if exists rating_system_by_country_read on public.rating_system_by_country;
create policy rating_system_by_country_read on public.rating_system_by_country for select to anon, authenticated using (true);
revoke all on public.rating_system_by_country from anon, authenticated;
grant select on public.rating_system_by_country to anon, authenticated;

alter table public.account_details add column if not exists rating_system text not null default 'auto';
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'account_details_rating_system_check') then
    alter table public.account_details add constraint account_details_rating_system_check check (rating_system in ('auto', 'uk', 'us'));
  end if;
end $$;

create or replace function public.set_rating_system(p_system text)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_user uuid := auth.uid();
begin
  if v_user is null then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_system is null or p_system not in ('auto', 'uk', 'us') then
    raise exception 'unknown rating system' using errcode = '22023';
  end if;
  update public.account_details set rating_system = p_system, updated_at = now() where user_id = v_user;
end $$;
revoke all on function public.set_rating_system(text) from public, anon;
grant execute on function public.set_rating_system(text) to authenticated;

-- The system in force for this session: the account's own choice, else the country of the device of this session (else of the device
-- seen last), else british. Returns 'uk' or 'us'.
create or replace function public.my_rating_system()
returns text language plpgsql stable security definer set search_path = public as $$
declare
  v_user    uuid := auth.uid();
  v_session uuid := nullif(auth.jwt() ->> 'session_id', '')::uuid;
  v_choice  text;
  v_country text;
begin
  if v_user is null then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select rating_system into v_choice from public.account_details where user_id = v_user;
  if v_choice in ('uk', 'us') then
    return v_choice;
  end if;
  select last_country into v_country from public.account_devices
   where user_id = v_user and last_country is not null
   order by (session_id is not distinct from v_session) desc, last_seen desc
   limit 1;
  return coalesce((select system from public.rating_system_by_country where country = v_country), 'uk');
end $$;
revoke all on function public.my_rating_system() from public, anon;
grant execute on function public.my_rating_system() to authenticated;

insert into public.schema_versions (name) values ('rating_system') on conflict do nothing;

select name as applied, applied_at from public.schema_versions order by applied_at;
